import {DAYS,createTraveler,verdictFor,ACTION_NAMES} from './data.js';
import {createScene} from './scene.js';

const $=s=>document.querySelector(s), key='northgate-save-v1';
const icons={shield:'⬡',doc:'▤',scan:'⌗',check:'✓',close:'×',pause:'Ⅱ',sound:'♫',book:'▥'};
let state={day:1,index:0,run:0,credits:120,score:0,correct:0,total:0,integrity:100,combo:0,bestCombo:0,upgrades:{},history:[],elapsed:0};
let saved=false;try{const raw=JSON.parse(localStorage.getItem(key));if(raw&&raw.version===1&&Number.isInteger(raw.day)&&raw.day>=1&&raw.day<=5&&Number.isInteger(raw.index)&&raw.index>=0&&raw.index<6&&Array.isArray(raw.history)&&raw.upgrades&&typeof raw.credits==='number'&&Number.isFinite(raw.score)){state={...state,...raw};saved=true;}}catch{}
let p,portrait='',scene,tab='passport',reportTab='cargo',view='overview',scanned=false,uv=false,scanning=false,scanToken=0,marked=new Set(),questions=new Set(),decided=false,paused=false,modalOpen=false,muted=true,audioCtx,toastTimer,decisionTimer,bribeDone=false;
const app=$('#app');
app.innerHTML=`
 <header class="topbar">
  <a class="brand" href="#" aria-label="北境哨所主页"><span class="brand-icon">N<span>7</span></span><span><strong>NORTHGATE</strong><small>北境哨所 · 入境管理局</small></span></a>
  <div class="shift"><span class="eyebrow">CURRENT SHIFT</span><b id="day-label">第 01 日</b><span id="date-label"></span></div>
  <div class="header-stats"><div><small>绩效积分</small><strong id="score">0000</strong></div><div><small>可用经费</small><strong id="credits">₭ 120</strong></div><div class="integrity-stat"><small>纪律评级</small><strong id="integrity">100<span>/100</span></strong></div></div>
  <div class="top-actions"><button data-action="journal" title="执勤记录" aria-label="执勤记录">▥</button><button data-action="sound" title="开启音效" aria-label="开启音效" id="sound-btn">♫<i></i></button><button data-action="pause" title="暂停与帮助" aria-label="暂停与帮助">Ⅱ</button></div>
 </header>
 <main>
  <section class="world" aria-label="3D 边境检查站">
   <div id="scene"></div><div class="world-vignette"></div>
   <aside class="rule-panel">
    <div class="panel-kicker"><span class="live-dot"></span> 岗位 07 <span>北部边境</span></div>
    <h1>每一次放行，<br>都有分量。</h1>
    <div class="rule-heading"><span>▤ 当日通关指令</span><b id="rule-count">01—03</b></div>
    <div class="order-tag" id="order-tag">第 01 号通告</div><ol id="rules"></ol>
    <button class="text-button" data-action="briefing">查看完整通报 <span>↗</span></button>
    <div class="queue-panel"><div><span>本班检查进度</span><b id="queue-count">01 / 06</b></div><div class="queue-dots" id="queue-dots"></div><small id="day-title">雾中的第一班岗</small></div>
   </aside>
   <div class="scene-top"><span><i></i> 检查站在线</span><span id="field-date">1984.11.06</span><span id="weather">薄雾 / −2°C</span><span class="clock" id="clock">08:00</span></div>
   <div class="scene-label"><span class="crosshair">+</span><span>NORTH PASS<span>48° 17′ N · 22° 09′ E</span></span></div>
   <div class="scene-controls"><div class="camera-tabs" role="group" aria-label="镜头视角"><button class="active" data-view="overview"><kbd>1</kbd> 哨所全景</button><button data-view="docs"><kbd>2</kbd> 近距离核验</button><button data-view="cargo"><kbd>3</kbd> 货物查验</button></div><span class="camera-hint">拖动旋转 · 滚轮缩放</span></div>
   <div class="traveler-bubble"><span class="traveler-label">当前受检者 <span id="traveler-index">NO. 001</span></span><strong id="traveler-name"></strong><p id="traveler-quote"></p></div>
   <div class="result-banner" id="result-banner" hidden aria-live="polite"></div>
  </section>
  <section class="desk" aria-label="检查工作台">
   <div class="document-area"><div class="desk-heading"><span>01 <b>证件核验</b></span><button data-action="uv" id="uv-btn"><span>◈</span> 紫外检验 <kbd>U</kbd></button></div><div class="doc-tabs" role="tablist"><button role="tab" class="active" data-tab="passport">护照</button><button role="tab" data-tab="permit">入境许可</button><button role="tab" data-tab="health">附加证明 <span id="cert-count"></span></button></div><div id="document" class="document"></div></div>
   <div class="inspection-area"><div class="desk-heading"><span>02 <b>货物与问询</b></span><span class="inspection-status" id="scan-status">等待扫描</span></div><div class="report-tabs" role="tablist"><button role="tab" class="active" data-report="cargo">货物清单</button><button role="tab" data-report="interview">询问旅客</button><button role="tab" data-report="evidence">标记证据 <span id="evidence-count">0</span></button></div><div id="report" class="report"></div></div>
   <div class="decision-area"><div class="desk-heading"><span>03 <b>最终决定</b></span><span class="live-dot"></span></div><p id="decision-hint">检查证件与货物后作出判断。</p><button class="decision approve" data-decision="approve"><span class="decision-icon">✓</span><span>批准入境<small>APPROVE ENTRY</small></span><kbd>A</kbd></button><button class="decision deny" data-decision="deny"><span class="decision-icon">×</span><span>拒绝入境<small>DENY ENTRY</small></span><kbd>R</kbd></button><button class="decision detain" data-decision="detain"><span class="decision-icon">⌗</span><span>依法拘留<small>DETAIN SUBJECT</small></span><kbd>D</kbd></button><div class="combo" id="combo">秉公执勤，守住边境。</div></div>
  </section>
 </main>
 <footer><span><i class="live-dot"></i> 北境联邦 · 边境管理局</span><span id="save-state">进度自动保存在此设备</span><span>行动优先级：拘留 > 拒绝 > 批准 <button data-action="help">操作指南 ?</button></span></footer>
 <div class="toast" id="toast" role="status" hidden></div>
 <div class="modal-layer" id="modal-layer" hidden><section class="modal" id="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"></section></div>`;

try{scene=createScene($('#scene'),kind=>{if(kind==='cargo')startScan();if(kind==='docs'){setTab('passport');setView('docs');}if(kind==='talk'){setReport('interview');setView('docs');}});}catch(e){$('#scene').innerHTML='<div class="webgl-fallback"><b>3D 场景暂不可用</b><p>请在浏览器中启用硬件加速后刷新。证件检查仍可游玩。</p></div>';console.error(e);}

function persist(){try{localStorage.setItem(key,JSON.stringify({...state,version:1}));$('#save-state').textContent='✓ 已自动保存到此设备';}catch{$('#save-state').textContent='当前浏览器无法保存进度';}}
function sound(type='click'){if(muted)return;try{audioCtx??=new (window.AudioContext||window.webkitAudioContext)();audioCtx.resume();const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.connect(gain);gain.connect(audioCtx.destination);osc.type=type==='bad'?'sawtooth':'sine';const f=type==='good'?650:type==='bad'?140:type==='scan'?390:430;osc.frequency.setValueAtTime(f,audioCtx.currentTime);osc.frequency.exponentialRampToValueAtTime(type==='good'?960:f*.6,audioCtx.currentTime+.15);gain.gain.setValueAtTime(.07,audioCtx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.24);osc.start();osc.stop(audioCtx.currentTime+.25);}catch{}}
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,3500);}
function updateStats(){$('#score').textContent=String(state.score).padStart(4,'0');$('#credits').textContent=`₭ ${state.credits}`;$('#integrity').innerHTML=`${state.integrity}<span>/100</span>`;$('#combo').innerHTML=state.combo>=2?`<span>✦</span> 连续正确 ${state.combo} 次`:'秉公执勤，守住边境。';}
function loadCase(){p=createTraveler(state.day,state.index,state.run);scanned=false;uv=!!state.upgrades.uv;scanning=false;scanToken++;marked=new Set();questions=new Set();bribeDone=false;decided=false;tab='passport';reportTab='cargo';scene?.setTraveler(p);scene?.setDay(state.day);portrait=scene?.portrait(p)||'';$('#result-banner').hidden=true;$('.traveler-bubble').hidden=false;render();setView('overview');const completed=state.history.filter(h=>h.day===state.day);if(completed.length>state.index){decided=true;scanned=true;uv=state.day>=2||uv;renderDoc();renderReport();showResult(completed[state.index]);updateChecks();}}
function render(){const day=DAYS[state.day-1];$('#day-label').textContent=`第 ${String(state.day).padStart(2,'0')} 日`;$('#date-label').textContent=day.date;$('#field-date').textContent=day.date;$('#weather').textContent=day.weather;$('#rules').innerHTML=day.rules.map((r,i)=>`<li><span>${String(i+1).padStart(2,'0')}</span><p>${r}</p></li>`).join('');$('#rule-count').textContent=`01—${String(day.rules.length).padStart(2,'0')}`;$('#order-tag').textContent=`第 ${String(state.day).padStart(2,'0')} 号通告${state.day>1?' · 规则已更新':''}`;$('#queue-count').textContent=`${String(state.index+1).padStart(2,'0')} / 06`;$('#queue-dots').innerHTML=Array.from({length:6},(_,i)=>`<span class="${i<state.index?'done':i===state.index?'current':''}"></span>`).join('');$('#day-title').textContent=day.title;$('#traveler-index').textContent=`NO. ${String((state.day-1)*6+state.index+1).padStart(3,'0')}`;$('#traveler-name').textContent=p.name;$('#traveler-quote').textContent=`“${p.quote}”`;$('#cert-count').textContent=state.day>=3?'!':'';updateStats();renderDoc();renderReport();updateChecks();}
const field=(label,value,id,cls='')=>`<button class="doc-field ${marked.has(id)?'marked':''} ${cls}" data-evidence="${id}" data-label="${label}：${value}" title="点击标记此项证据"><small>${label}</small><b>${value}</b></button>`;
function renderDoc(){document.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);b.setAttribute('aria-selected',b.dataset.tab===tab);});let html='';
 if(tab==='passport')html=`<div class="passport ${uv?'uv-active':''}"><div class="passport-top"><span>⬡ ${p.country.toUpperCase()} · REPUBLIC</span><b>护照 / PASSPORT</b></div><div class="passport-body"><div class="passport-photo">${portrait?`<img src="${portrait}" alt="${p.name}的证件照">`:'<span>证件照</span>'}<span>${p.country}</span></div><div class="passport-fields">${field('姓名 / FULL NAME',p.name,'name','full')}${field('国籍',p.country,'country')}${field('出生日期',p.birth,'birth')}${field('护照号码',p.number,'number')}${field('有效期至',p.expires,'expiry')}</div></div><div class="machine-line">P&lt;${p.country==='阿尔登'?'ARD':'FOR'}&lt;${p.number}&lt;&lt;&lt;&lt;&lt;&lt;&lt;&lt;19841106</div>${uv?`<div class="uv-seal ${p.authentic?'genuine':'fake'}">${p.authentic?'◈ 防伪印记有效':'! 未发现防伪印记'}</div>`:''}</div>`;
 if(tab==='permit')html=`<div class="permit paper"><div class="paper-title">入境许可 <span>ENTRY PERMIT</span></div><div class="permit-grid">${field('持证人',p.permitName,'permitName')}${field('护照号',p.permitNumber,'permitNumber')}${field('入境目的',p.purpose,'purpose')}${field('停留期限',`${p.duration} 天`,'duration')}</div><div class="permit-footer"><span>签发：北境移民管理局<br>此许可须与有效护照一同使用</span><b>已核发<br>APPROVED</b></div></div>`;
 if(tab==='health')html=`<div class="certificates">${[['health','检疫证明',p.health,'卫生部 · 有效绿色通行证明',state.day>=3],['work','工作许可证',p.work,'劳工部 · 有效工作许可',state.day>=3&&p.purpose==='工作'],['medical','药品运输证',p.medicinePermit,'卫生部 · 药品运输许可',state.day>=5&&p.goods.some(g=>g.medical)]].map(([id,title,valid,detail,needed])=>`<button class="certificate ${marked.has(id)?'marked':''}" data-evidence="${id}" data-label="${title}：${valid?'有效':'未提供'}"><span class="cert-icon ${valid?'':'missing'}">${valid?'▧':'!'}</span><span><b>${title}${needed?'<em>须检查</em>':''}</b><small>${valid?detail:'未提供此证明'}</small></span><span>${valid?'✓':'—'}</span></button>`).join('')}<small class="muted">按当日规则确认所需文件。</small></div>`;
 $('#document').innerHTML=html;$('#uv-btn').classList.toggle('checked',uv);$('#uv-btn').innerHTML=uv?'◈ 已检验 <kbd>U</kbd>':'◈ 紫外检验 <kbd>U</kbd>';
}
function renderReport(){document.querySelectorAll('[data-report]').forEach(b=>{b.classList.toggle('active',b.dataset.report===reportTab);b.setAttribute('aria-selected',b.dataset.report===reportTab);});$('#evidence-count').textContent=marked.size;
 if(reportTab==='cargo'){const goods=scanned?p.goods:p.goods.filter(g=>g.declared);const weight=goods.reduce((s,g)=>s+g.weight,0);$('#report').innerHTML=`<div class="manifest-top"><span>货物申报单 <small>#CN-${String(470+state.total).padStart(4,'0')}</small></span><b>${scanned?'扫描完成':'旅客申报'}</b></div><table class="manifest"><thead><tr><th>货物名称</th><th>数量</th><th>重量</th><th>状态</th></tr></thead><tbody>${goods.map(g=>`<tr class="${scanned&&!g.declared?'suspicious':''}"><td>${g.name}</td><td>× ${g.qty}</td><td>${g.weight} kg</td><td>${scanned?(g.illegal?'违禁品':g.declared?'已申报':'未申报'):'待核验'}</td></tr>`).join('')}</tbody></table><div class="weight-row"><span>${scanned?'实际总重':'申报总重'}</span><b class="${scanned&&state.day>=2&&weight>40?'danger':''}">${weight} <small>kg</small></b><span>${state.day>=2?'限重 40 kg':'例行检查'}</span></div><button class="scan-button ${scanned?'complete':''}" data-action="scan" ${scanning||scanned?'disabled':''}><span>${scanning?'◌ 正在进行 X 光扫描…':scanned?'✓ 货物扫描已完成':'⌗ 扫描货物'}</span><span>${scanning?'扫描中':scanned?'已记录':'X-RAY'} <kbd>空格</kbd></span></button>`;}
 if(reportTab==='interview')$('#report').innerHTML=`<div class="interview"><p>${questions.size?`“${p.answer}”`:'询问旅行目的与行李。仅根据证件和实际货物作出判断。'}</p><div>${[['purpose','入境目的是什么？'],['goods','行李已全部申报吗？'],['documents','解释证件上的信息']].map(([id,q])=>`<button data-question="${id}" class="${questions.has(id)?'asked':''}">${questions.has(id)?'✓ ':''}${q}</button>`).join('')}</div>${p.bribe&&questions.has('goods')?`<div class="bribe"><span>旅客悄悄递来 ₭ ${p.bribe}，希望免检。</span>${bribeDone?'<b>已拒绝并记录 · 纪律 +5</b>':'<button data-action="bribe">拒绝贿赂并记录</button>'}</div>`:''}</div>`;
 if(reportTab==='evidence')$('#report').innerHTML=`<div class="evidence-list">${marked.size?[...marked].map(m=>`<div><span>⚑</span><b>${evidenceLabel(m)}</b><button data-evidence="${m}" aria-label="移除此证据">×</button></div>`).join(''):'<div class="empty-evidence"><span>⚑</span><b>还没有标记证据</b><p>点击证件字段即可标记。证据便签帮助你比对，不会自动给出答案。</p></div>'}${scanned?`<div class="automatic-note">✓ X 光检查已完成 · 实际 ${p.goods.reduce((n,g)=>n+g.weight,0)} kg</div>`:''}${uv?`<div class="automatic-note">◈ 紫外检验：${p.authentic?'防伪印记有效':'缺少防伪印记'}</div>`:''}</div>`;
}
function evidenceLabel(id){const map={name:`姓名：${p.name}`,country:`国籍：${p.country}`,birth:`出生日期：${p.birth}`,number:`护照号：${p.number}`,expiry:`到期日：${p.expires}`,permitName:`许可姓名：${p.permitName}`,permitNumber:`许可护照号：${p.permitNumber}`,purpose:`目的：${p.purpose}`,duration:`停留：${p.duration} 天`,health:`检疫证明：${p.health?'有效':'未提供'}`,work:`工作证：${p.work?'有效':'未提供'}`,medical:`药品运输证：${p.medicinePermit?'有效':'未提供'}`};return map[id]||id;}
function updateChecks(){$('#scan-status').textContent=scanning?'扫描进行中':scanned?'✓ 货物已查验':'等待扫描';$('#scan-status').classList.toggle('ready',scanned);$('#decision-hint').textContent=!scanned?'先完成 X 光扫描，核对实际货物。':state.day>=2&&!uv?'完成紫外检验后即可作出决定。':'检查已完成，请依据当日规则决定。';document.querySelectorAll('[data-decision]').forEach(b=>b.disabled=decided||scanning);}
function setTab(t){if(!['passport','permit','health'].includes(t))return;tab=t;renderDoc();sound();}
function setReport(t){if(!['cargo','interview','evidence'].includes(t))return;reportTab=t;renderReport();sound();}
function setView(v){view=v;scene?.setView(v);document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===v));}
function startScan(){if(decided||scanning||modalOpen)return;if(scanned){setReport('cargo');toast('本次货物已经扫描完成。');return;}scanning=true;const token=++scanToken;const ms=state.upgrades.scanner?650:2100;scene?.scan(ms);setView('cargo');reportTab='cargo';renderReport();updateChecks();sound('scan');setTimeout(()=>{if(token!==scanToken)return;scanning=false;scanned=true;renderReport();updateChecks();sound('good');toast(p.goods.some(g=>!g.declared)?'扫描发现申报单之外的物品，请检查清单。':'货物扫描已完成，实际货物已记录。');},ms);}
function doUV(){if(decided||modalOpen)return;uv=true;tab='passport';renderDoc();renderReport();updateChecks();sound('scan');toast(p.authentic?'紫外灯下可见有效防伪印记。':'未检测到防伪印记。请查阅当日处置规则。');}
function decide(action){if(!['approve','deny','detain'].includes(action)||decided||modalOpen||paused)return false;if(!scanned){toast('请先扫描货物（空格），确保没有遗漏违禁物品。');return false;}if(state.day>=2&&!uv){toast('今日要求检查防伪印记，请使用紫外检验（U）。');return false;}const result=verdictFor(p,state.day),ok=result.action===action;decided=true;state.total++;state.correct+=ok?1:0;state.combo=ok?state.combo+1:0;state.bestCombo=Math.max(state.bestCombo,state.combo);const bonus=ok?20+Math.min(state.combo-1,5)*3:action==='detain'?-35:-20;state.score=Math.max(0,state.score+bonus);state.credits=Math.max(0,state.credits+(ok?25:-15));state.integrity=Math.max(0,Math.min(100,state.integrity+(ok?1:action==='detain'?-12:-7)));state.history.push({day:state.day,name:p.name,number:p.number,chosen:action,expected:result.action,ok,reasons:result.reasons,bonus});scene?.leave(action);sound(ok?'good':'bad');updateStats();updateChecks();showResult(state.history.at(-1));persist();return {correct:ok,...result};}
function showResult(h){$('.traveler-bubble').hidden=true;$('#result-banner').className=`result-banner ${h.ok?'correct':'incorrect'}`;$('#result-banner').innerHTML=`<span class="result-symbol">${h.ok?'✓':'!'}</span><div><small>${h.ok?'判定正确 · +'+h.bonus+' 积分':'收到执勤纠错 · '+h.bonus+' 积分'}</small><h2>${ACTION_NAMES[h.chosen]}</h2><p>${h.ok?h.reasons.join('；'):`应${ACTION_NAMES[h.expected]}：${h.reasons.join('；')}`}</p></div><button data-action="next">${state.index===5?'本班结算':'下一位旅客'} <kbd>Enter</kbd></button>`;$('#result-banner').hidden=false;}

function next(){if(!decided)return;if(state.index===5){endDay();return;}state.index++;persist();loadCase();}
let previousFocus=null;
function showModal(html){previousFocus=document.activeElement;modalOpen=true;paused=true;$('#modal').innerHTML=html;$('#modal-layer').hidden=false;$('#modal').querySelector('button')?.focus();}
function closeModal(){modalOpen=false;paused=false;$('#modal-layer').hidden=true;previousFocus?.focus?.();}
function header(kicker,title){return `<div class="modal-kicker">${kicker}</div><h2 id="modal-title">${title}</h2>`;}
function briefing(){const d=DAYS[state.day-1];showModal(`${header('MINISTRY OF BORDER SECURITY',`第 ${state.day} 日 · ${d.title}`)}<p class="modal-lead">${d.memo}</p><div class="new-order"><b>本日重点</b><p>${d.newRule}</p></div><ol class="brief-rules">${d.rules.map(r=>`<li>${r}</li>`).join('')}</ol><p class="muted">${state.day>=2?'今日起每人必须进行紫外检验。':'提示：护照到期日等于今天时仍有效。'} 拘留条件优先于普通拒绝条件。</p><button class="primary-button" data-action="close">已阅，开始执勤</button>`);}
function help(){showModal(`${header('FIELD MANUAL / 07','检查员操作手册')}<div class="help-steps"><div><b>01 / 核验身份</b><p>比较护照与入境许可上的姓名和号码，检查护照到期日。点击字段可加入证据便签。</p></div><div><b>02 / 检查货物</b><p>空格开始 X 光扫描。未申报货物会在扫描后显示；第 2 日起还须按 U 检验防伪。</p></div><div><b>03 / 依据规则决定</b><p>合规按 A 批准；普通违规按 R 拒绝；违禁品、通缉或规定中的伪造证件按 D 拘留。</p></div></div><div class="shortcut-grid"><span><kbd>1 / 2 / 3</kbd> 切换镜头</span><span><kbd>Enter</kbd> 下一位</span><span><kbd>Esc</kbd> 暂停</span><span><kbd>U</kbd> 紫外检验</span></div><p class="muted">每班 6 人，共 5 天。没有阅读倒计时。日终获得经费，可升级设备。进度仅保存在当前设备。</p><button class="primary-button" data-action="close">返回哨所</button>`);}
function pause(){showModal(`${header('SHIFT PAUSED','执勤已暂停')}<p class="modal-lead">第 ${state.day} 日 · 已完成 ${state.index}/6 位旅客</p><div class="pause-actions"><button class="primary-button" data-action="close">继续执勤</button><button class="secondary-button" data-action="help">查看操作指南</button><button class="text-button danger" data-action="restart-confirm">重新开始战役</button></div>`);}
function journal(){showModal(`${header('OFFICER’S LOG','执勤记录')}<div class="journal-stats"><b>${state.correct} / ${state.total}<small>正确判定</small></b><b>${state.total?Math.round(state.correct/state.total*100):0}%<small>准确率</small></b><b>${state.bestCombo}<small>最高连对</small></b></div><div class="journal-list">${state.history.length?state.history.slice().reverse().map(h=>`<article><span class="${h.ok?'good':'danger'}">${h.ok?'✓':'×'}</span><div><b>第 ${h.day} 日 · ${h.name}</b><small>${h.number} · ${ACTION_NAMES[h.chosen]}${h.ok?'':` / 应${ACTION_NAMES[h.expected]}`}</small><p>${h.reasons.join('；')}</p></div></article>`).join(''):'<p class="muted">完成第一位旅客检查后，记录会保存在这里。</p>'}</div><button class="primary-button" data-action="close">返回工作台</button>`);}
function endDay(){const entries=state.history.filter(h=>h.day===state.day),correct=entries.filter(h=>h.ok).length;const final=state.day===5;showModal(`${header(final?'CAMPAIGN COMPLETE':'END OF SHIFT',final?'边境长夜，终于天明。':`第 ${state.day} 日执勤结束`)}<p class="modal-lead">${final?'五天的边境执勤已经结束。每一个决定，都成为了这座哨所的记录。':DAYS[state.day-1].title+' · 值班记录已归档'}</p><div class="journal-stats"><b>${correct}/6<small>本班正确</small></b><b>${state.score}<small>总积分</small></b><b>₭ ${state.credits}<small>可用经费</small></b></div>${final?`<div class="ending-badge"><span>⬡</span><b>${state.correct>=27?'边境守望者':state.correct>=21?'可靠的检查员':state.correct>=15?'成长中的执勤官':'边境见习生'}</b><p>总准确率 ${Math.round(state.correct/state.total*100)}% · 最高连续正确 ${state.bestCombo} 次</p></div>`:`<h3>设备补给</h3><div class="upgrades">${[['scanner','高速扫描仪',80,'X 光扫描时间缩短至 0.65 秒'],['uv','自动防伪灯',100,'每位旅客自动完成紫外检验']].map(([id,title,cost,desc])=>`<button data-upgrade="${id}" ${state.upgrades[id]||state.credits<cost?'disabled':''}><span><b>${title}</b><small>${desc}</small></span><strong>${state.upgrades[id]?'已配备':'₭ '+cost}</strong></button>`).join('')}</div><div class="tomorrow"><small>下一班情报</small><p>${DAYS[state.day].newRule}</p></div>`}<button class="primary-button" data-action="${final?'restart-confirm':'advance'}">${final?'开启新的战役':'领取下一班指令'}</button><button class="text-button" data-action="journal-summary">查看执勤记录</button>`);persist();}
function advance(){if(state.day>=5)return;state.day++;state.index=0;persist();closeModal();loadCase();briefing();}
function reset(){scanToken++;clearTimeout(decisionTimer);const run=state.run+1;state={day:1,index:0,run,credits:120,score:0,correct:0,total:0,integrity:100,combo:0,bestCombo:0,upgrades:{},history:[],elapsed:0};closeModal();persist();loadCase();briefing();}
function restartConfirm(){showModal(`${header('NEW CAMPAIGN','重新开始五日战役？')}<p class="modal-lead">这将清除当前设备上的积分、经费、装备和执勤记录。</p><button class="primary-button" data-action="restart">确认重新开始</button><button class="secondary-button" data-action="close">保留当前进度</button>`);}

app.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.disabled)return;if(b.dataset.tab)setTab(b.dataset.tab);if(b.dataset.report)setReport(b.dataset.report);if(b.dataset.view)setView(b.dataset.view);if(b.dataset.decision)decide(b.dataset.decision);if(b.dataset.evidence){marked.has(b.dataset.evidence)?marked.delete(b.dataset.evidence):marked.add(b.dataset.evidence);renderDoc();renderReport();sound();}if(b.dataset.question){questions.add(b.dataset.question);if(b.dataset.question==='purpose')toast(`最终申报目的：${p.purpose}，停留 ${p.duration} 天。`);renderReport();sound();}if(b.dataset.upgrade){const id=b.dataset.upgrade,cost=id==='scanner'?80:100;if(!state.upgrades[id]&&state.credits>=cost){state.upgrades[id]=true;state.credits-=cost;persist();updateStats();endDay();sound('good');}}const a=b.dataset.action;if(!a)return;({scan:startScan,uv:doUV,next,briefing,help,pause,journal,close:closeModal,advance,restart:reset,'restart-confirm':restartConfirm,'journal-summary':()=>{journal();const btn=$('#modal .primary-button');btn.dataset.action='summary';btn.textContent='返回本班结算';},summary:endDay,bribe:()=>{if(bribeDone)return;bribeDone=true;state.integrity=Math.min(100,state.integrity+5);updateStats();renderReport();toast('拒绝贿赂已记入档案，纪律 +5。');},sound:()=>{muted=!muted;$('#sound-btn').classList.toggle('enabled',!muted);$('#sound-btn').setAttribute('aria-label',muted?'开启音效':'关闭音效');$('#sound-btn').title=muted?'开启音效':'关闭音效';sound();toast(muted?'音效已关闭':'音效已开启');}})[a]?.();});
document.addEventListener('keydown',e=>{if(e.key==='Tab'&&modalOpen){const focus=[...$('#modal').querySelectorAll('button:not(:disabled),[tabindex="0"]')];if(e.shiftKey&&document.activeElement===focus[0]){e.preventDefault();focus.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===focus.at(-1)){e.preventDefault();focus[0]?.focus();}return;}if(e.key==='Escape'){e.preventDefault();modalOpen?closeModal():pause();return;}if(modalOpen||e.repeat||e.ctrlKey||e.metaKey||e.altKey||e.target.matches('input,textarea,select'))return;const k=e.key.toLowerCase();if([' ','a','r','d','u','1','2','3','enter'].includes(k))e.preventDefault();if(k===' ')startScan();if(k==='u')doUV();if(k==='a')decide('approve');if(k==='r')decide('deny');if(k==='d')decide('detain');if(k==='enter')next();if(['1','2','3'].includes(k))setView(['overview','docs','cargo'][Number(k)-1]);});
setInterval(()=>{if(!paused&&!decided){state.elapsed++;const mins=8*60+Math.floor(state.elapsed/5);$('#clock').textContent=`${String(Math.floor(mins/60)%24).padStart(2,'0')}:${String(mins%60).padStart(2,'0')}`;}},1000);
loadCase();if(saved)toast('已恢复此设备上的执勤进度。');else toast('欢迎上岗。查看证件，按空格扫描货物。');
// Reconcile a save captured on an end-of-shift summary, without awarding the final case twice.
if(state.history.filter(h=>h.day===state.day).length===6){decided=true;updateChecks();endDay();}

const context=document.modelContext;
if(context?.registerTool){const lifecycle=new AbortController();const register=t=>{try{Promise.resolve(context.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
 register({name:'read_checkpoint',title:'读取检查站',description:'读取当前当日指令、证件和已经完成的检查结果，不会揭示未扫描货物。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>({day:state.day,rules:DAYS[state.day-1].rules,traveler:{name:p.name,number:p.number,country:p.country,expires:p.expires,permitName:p.permitName,purpose:p.purpose,health:p.health,work:p.work},goods:scanned?p.goods:p.goods.filter(g=>g.declared),scanned,uv:uv?p.authentic:null,decided})});
 register({name:'inspect_checkpoint',title:'检查旅客',description:'执行与界面相同的货物扫描或紫外检验。',inputSchema:{type:'object',properties:{inspection:{type:'string',enum:['cargo','uv']}},required:['inspection'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(!input||!['cargo','uv'].includes(input.inspection))throw new Error('inspection must be cargo or uv');if(modalOpen||decided)throw new Error('当前不在检查阶段');if(input.inspection==='uv')doUV();else{startScan();await new Promise(r=>setTimeout(r,state.upgrades.scanner?700:2200));}return {scanned,uv,goods:scanned?p.goods:null,authentic:uv?p.authentic:null};}});
 register({name:'decide_checkpoint',title:'提交边检决定',description:'完成当前旅客的批准、拒绝或拘留判定，影响积分与经费。必须先完成必要检查。',inputSchema:{type:'object',properties:{decision:{type:'string',enum:['approve','deny','detain']}},required:['decision'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!['approve','deny','detain'].includes(input.decision))throw new Error('Invalid decision');if(!scanned||(state.day>=2&&!uv))throw new Error('请先完成必要检查');const r=decide(input.decision);if(!r)throw new Error('当前无法提交决定');return r;}});
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
